/**
 * Deterministic copy-gate DATA (paid-journey v2 M2a.1, gate A1-A4).
 *
 * Every Hebrew token below is copied byte-exact from a reviewer example or an
 * existing repo string (the `source` says where); none is authored. Generated by a
 * script that asserts each token against its source file:line. Add tokens only as
 * byte-exact patches from language-qa (Noa) / waocopy, never typed from memory.
 * Logic lives in copyGates.ts (zero Hebrew bytes).
 */

export interface GateToken {
  token: string;
  /** Allow attached Hebrew prefix letters (vav/shin/he/bet/kaf/lamed/mem) before the token. */
  allowPrefix: boolean;
  source: string;
}

